/**
 * <assistant-orb> — a realistic CSS orb for AI assistants.
 *
 *   <assistant-orb variant="sphere" state="idle" size="168" hue="265"></assistant-orb>
 *
 * Zero dependencies, no build step for consumers, no network requests.
 * This file is GENERATED by `npm run build` — edit src/component.js and
 * orb.css instead. The orb animation is 100% CSS; a few lines of JS only
 * keep the attributes and the aria label in sync.
 */
(function () {
  "use strict";

  /* Build-time injection: the stylesheet and the per-variant markup. */
  var CSS = "__ORB_CSS__";
  var MARKUP = __ORB_MARKUP__;

  var VARIANTS = Object.keys(MARKUP);
  var STATES = ["idle", "listening", "thinking", "speaking"];

  var HOST_CSS =
    ":host{display:inline-block;line-height:0}" +
    ":host([hidden]){display:none}" +
    ".orb-stage.is-paused *{animation-play-state:paused!important}";

  function number(value, fallback) {
    var parsed = parseFloat(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  }

  function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
  }

  class AssistantOrb extends HTMLElement {
    static get observedAttributes() {
      return ["variant", "state", "size", "hue", "speed", "label", "paused", "decorative"];
    }

    constructor() {
      super();
      this._root = this.attachShadow({ mode: "open" });
      this._stage = null;
    }

    connectedCallback() {
      if (!this._stage) this._mount();
      this._sync();
    }

    attributeChangedCallback(name, oldValue, newValue) {
      if (!this._stage) return;

      if (name === "variant") {
        this._mount();
      } else {
        this._sync();
      }

      if (name === "state" && oldValue !== newValue) {
        this.dispatchEvent(
          new CustomEvent("orbstatechange", {
            bubbles: true,
            detail: { state: this.state, previous: oldValue || "idle" },
          })
        );
      }
    }

    get variant() {
      return this._variant();
    }
    set variant(value) {
      this.setAttribute("variant", value);
    }

    get state() {
      return this._state();
    }
    set state(value) {
      this.setAttribute("state", value);
    }

    /** Fluent helper: orb.setState("thinking") */
    setState(value) {
      this.setAttribute("state", value);
      return this;
    }

    _state() {
      var state = (this.getAttribute("state") || "idle").toLowerCase();
      return STATES.indexOf(state) === -1 ? "idle" : state;
    }

    _variant() {
      var variant = (this.getAttribute("variant") || "sphere").toLowerCase();
      if (!MARKUP[variant]) {
        console.warn(
          '[assistant-orb] unknown variant "' + variant + '". Known variants: ' + VARIANTS.join(", ") + "."
        );
        variant = "sphere";
      }
      return variant;
    }

    _mount() {
      var variant = this._variant();
      this._root.innerHTML =
        "<style>" +
        CSS +
        HOST_CSS +
        "</style>" +
        '<div class="orb-stage" data-state="' +
        this._state() +
        '">' +
        MARKUP[variant] +
        "</div>";
      this._stage = this._root.querySelector(".orb-stage");
      this._sync();
    }

    _sync() {
      var stage = this._stage;
      if (!stage) return;

      var state = this._state();
      var label = this.getAttribute("label") || "Assistant orb";

      stage.dataset.state = state;
      stage.style.setProperty("--orb-h", String(clamp(number(this.getAttribute("hue"), 265), 0, 360)));
      stage.style.setProperty("--orb-size", clamp(number(this.getAttribute("size"), 168), 24, 900) + "px");
      stage.style.setProperty(
        "--orb-speed",
        String(clamp(number(this.getAttribute("speed"), 1), 0.1, 3))
      );

      stage.classList.toggle("is-paused", this.hasAttribute("paused"));

      if (this.hasAttribute("decorative")) {
        stage.setAttribute("aria-hidden", "true");
        stage.removeAttribute("role");
        stage.removeAttribute("aria-label");
      } else {
        stage.removeAttribute("aria-hidden");
        stage.setAttribute("role", "img");
        stage.setAttribute("aria-label", label + ", " + state);
      }
    }
  }

  if (!customElements.get("assistant-orb")) {
    customElements.define("assistant-orb", AssistantOrb);
  }

  window.AssistantOrb = AssistantOrb;
})();
